r_luck"], "attributes": {"observed_research_question": "Game retrospective template preview OKC vs PHX (unpopulated)", "auto_outcome_status": "untestable", "observed_hypothesis": "Pre-game vs halftime vs post-game pipeline runs on OKC-PHX Game 1 can be compared to observed stats.", "observed_result": "All sections [MODELED pending] / [DELTA pending] / [OBSERVED pending]. Spearman 0.54 and MAE 0.0922 are copied from the holdout rank study, not computed here.", "auto_failure_mechanism": "A_unanswerable (question not answerable with the data or design)", "observed_failure_evidence": "Pipeline runs were never supplied; 0 possession sequences in the train split field.", "observed_sample_and_power": "NOT_RECORDED", "auto_validation_status": "same_pipeline_validation; evidence: APPA-068: 'pending]. spearman 0.54 and mae 0.0922 are copied from the holdout rank study, not computed here. placeholder preview, not a c'", "observed_verdict": "abandoned"}, "relationships": [{"rel": "auto_related_family", "node": "FAM:SF-APPA-063"}]}, {"id": "FAM:SF-CHT-009", "label": "Study family SF-CHT-009: Superstar suppression by lineup and forced play type", "score": 0.599, "reached_via": ["request matches RQC:RQC-055 (0.72); FAM:SF-CHT-009 auto_addresses_question RQC:RQC-055", "request matches DS:NBA_play_by_play_possessions_and_reconstructed_lineups (0.69); FAM:SF-CHT-009 auto_uses_dataset DS:NBA_play_by_play_possessions_and_reconstructed_lineups"], "attributes": {"observed_research_question": "Superstar suppression by lineup and forced play type", "auto_outcome_status": "not a hypothesis test", "observed_hypothesis": "Named star initiators have identifiable lineup and forced-play-type suppressors in the possession graph.", "observed_result": "Jokic vs MIN lineup PPP 0.814, -0.385 (n=59); Curry vs HOU 0.851, -0.358 (n=47); Doncic vs LAC 0.733, -0.396 (n=30); Giannis forced PULL_UP 0.848, -0.540 vs preferred DRIVE (largest gap).", "auto_failure_mechanism": "E_unclear (mechanism unclear from